SELECT jsonb_build_object('project','qvplwejffhjvxaypmjut','at',now(),'works',(SELECT count(*) FROM public.works),'editions',(SELECT count(*) FROM public.editions),'nlAvailableWorks',(SELECT count(DISTINCT work_id) FROM public.editions WHERE lower(trim(language)) IN ('nl','nld','dut')),'approvedNlSummaries',(SELECT count(*) FROM public.catalog_work_descriptions WHERE language='nl' AND review_status='approved'),'approvedEnSummaries',(SELECT count(*) FROM public.catalog_work_descriptions WHERE language='en' AND review_status='approved'),'nlWorkIds',(SELECT jsonb_agg(work_id ORDER BY work_id) FROM (SELECT DISTINCT work_id FROM public.editions WHERE lower(trim(language)) IN ('nl','nld','dut'))n),'editionLanguages',(SELECT jsonb_object_agg(language,n) FROM (SELECT coalesce(nullif(lower(trim(language)),''),'unknown') language,count(*) n FROM public.editions GROUP BY 1)t)) snapshot;
